  61: 'rainy', 63: 'rainy', 65: 'heavy rain', 66: 'freezing rain', 67: 'freezing rain',
  71: 'snowy', 73: 'snowy', 75: 'heavy snow', 77: 'snowy', 80: 'rain showers', 81: 'rain showers', 82: 'heavy rain showers',
