  where type = 'reminder' and status = 'open' and parent_id is null and recurrence is null and last_notified_at is not null
    and remind_at < (((now() at time zone 'Asia/Kolkata')::date)::timestamp at time zone 'Asia/Kolkata')
    and not (cardinality($1::text[]) > 0 and not exists (select 1 from unnest($1::text[]) s where lower(title) not like '%' || s || '%'))
  returning title
)
select (select count(*) from c)::int as closed, (select coalesce(json_agg(title), '[]'::json) from c) as titles`;

const data = $('Load data').first().json || {};
let mode = 'show';
try { mode = $('Due?').first().json.mode || 'show'; } catch (e) { mode = 'show'; }
const now = new Date();
const today = istDateStr(now);
const arr = (v) => (Array.isArray(v) ? v : []);
const nd = toIst(now);
const dateText = `${DAY_NAMES[nd.getUTCDay()]}, ${nd.getUTCDate()} ${MONTH_NAMES[nd.getUTCMonth()]}`;
const hour = nd.getUTCHours();
const greeting = hour < 12 ? 'Good morning' : hour < 17 ? 'Good afternoon' : 'Good evening';
const cap = (t) => (t ? t[0].toUpperCase() + t.slice(1) : t);
const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;
const list = (items, n) => items.slice(0, n).join(', ') + (items.length > n ? ` and ${items.length - n} more` : '');

// ---- weather ----
let weather = null;
const home = data.home_location && typeof data.home_location === 'object' ? data.home_location : null;
try {
  const w = $('Weather').first().json || {};
  if (home && w.daily && w.current && Array.isArray(w.daily.temperature_2m_max)) {
    const rain = Array.isArray(w.daily.precipitation_probability_max) ? w.daily.precipitation_probability_max[0] : null;
    weather = {
      place: home.name || 'your area', condition: WEATHER_WORDS[w.current.weather_code] || 'mixed',
      temp_c: Math.round(w.current.temperature_2m), high_c: Math.round(w.daily.temperature_2m_max[0]), low_c: Math.round(w.daily.temperature_2m_min[0]),
      rain_chance: Number.isFinite(rain) ? Math.round(rain) : null,
    };
  }
} catch (e) { weather = null; }

// ---- schedule: calendar events, reminders and dates that fall today ----
const schedule = [];
let calendarOk = true;
try {
  const cal = $('Calendar').all().map((i) => i.json || {});
  const events = cal.flatMap((j) => (Array.isArray(j.items) ? j.items : []));
  if (cal.length && cal[0].error) calendarOk = false;
  for (const e of events) {
    if (!e || e.status === 'cancelled' || typeof e.summary !== 'string') continue;
    if (typeof e.description === 'string' && e.description.startsWith('Sent by Jarvis')) continue; // Jarvis's own backup alerts
    const me = arr(e.attendees).find((a) => a && a.self);
    if (me && me.responseStatus === 'declined') continue;
    const dt = e.start && e.start.dateTime ? new Date(e.start.dateTime) : null;
    schedule.push({ kind: 'event', text: e.summary.slice(0, 100), at: dt ? dt.toISOString() : null, time: dt ? clock12(dt) : '', sort: dt ? dt.getTime() : -1 });
  }
} catch (e) { calendarOk = false; }
for (const r of arr(data.reminders_today)) {
  const at = new Date(r.remind_at);
  schedule.push({ kind: 'reminder', text: r.title, at: at.toISOString(), time: clock12(at), sort: at.getTime() });
}
for (const dte of arr(data.dates_soon)) {
  const at = new Date(dte.due_at);
  if (istDateStr(at) !== today) continue;
  const t = toIst(at); const timed = t.getUTCHours() + t.getUTCMinutes() > 0;
  schedule.push({ kind: 'date', text: dte.title, at: at.toISOString(), time: timed ? clock12(at) : '', sort: timed ? at.getTime() : -1 });
}
schedule.sort((a, b) => a.sort - b.sort);

// ---- tasks, dates, habits ----
const tasksDue = arr(data.tasks_due).map((t) => {
  const day = istDateStr(new Date(t.due_at));
  return { id: t.id, title: t.title, overdue: day < today, due_at: t.due_at };
});
const datesSoon = arr(data.dates_soon).filter((d) => istDateStr(new Date(d.due_at)) > today).map((d) => {
  const at = new Date(d.due_at); const t = toIst(at); const timed = t.getUTCHours() + t.getUTCMinutes() > 0;
  const days = Math.round((startOfIstDay(at).getTime() - startOfIstDay(now).getTime()) / 86400000);
  return { id: d.id, title: d.title, days, when: speakWhen(at, now, !timed) };
});
const habits = arr(data.habits).map((h) => {
  const info = streakInfo(arr(h.dates), today);
  return { id: h.id, title: h.title, streak: info.current, done: info.doneToday };
}).filter((h) => !h.done);

// ---- college work and email ----
const college = collegeSummary(arr(data.college_tasks), now);
const emailCounts = arr(data.email_counts);
const emailTop = arr(data.email_important);
const emailSynced = !!data.email_synced_at;
const mail = {};
for (const acc of ['personal', 'college']) {
  const n = (label) => Number((emailCounts.find((c) => c.account === acc && c.label === label) || {}).n) || 0;
  mail[acc] = { important: n('important'), normal: n('normal'), promo: n('promo'), top: emailTop.filter((m) => m.account === acc).slice(0, 3).map((m) => ({ from: m.sender, subject: m.subject })) };
}
const importantMail = mail.personal.important + mail.college.important;

// ---- yesterday's leftovers ----
const stale = arr(data.stale).map((r) => ({ id: r.id, title: r.title, when: speakWhen(new Date(r.remind_at), now, false) }));

// ---- spoken text ----
const spoken = [`${greeting}. It's ${dateText}.`];
if (weather) spoken.push(`In ${weather.place} it's ${weather.temp_c} degrees and ${weather.condition}. The high is ${weather.high_c} and the low ${weather.low_c}${weather.rain_chance ? `, with a ${weather.rain_chance} percent chance of rain` : ''}.`);
spoken.push(schedule.length ? `Today: ${list(schedule.map((s) => `${s.time ? s.time + ' ' : ''}${s.text}`), 5)}.` : 'Nothing is scheduled today.');
if (tasksDue.length) spoken.push(`Tasks due: ${list(tasksDue.map((t) => t.title + (t.overdue ? ' (overdue)' : '')), 4)}.`);
if (datesSoon.length) spoken.push(`Coming up: ${list(datesSoon.map((d) => `${d.title} ${d.when}`), 3)}.`);
if (habits.length) spoken.push(`Habits to check in: ${list(habits.map((h) => h.title + (h.streak ? `, ${h.streak} day streak` : '')), 4)}.`);
spoken.push(college.spoken);
if (emailSynced) {
  const lines = ['personal', 'college'].map((acc) => {
    const m = mail[acc];
    return m.important ? `${acc}, ${m.important} important${m.top.length ? ': ' + m.top.map((t) => `${t.from}, ${t.subject}`).join('; ') : ''}` : '';
  }).filter(Boolean);
  spoken.push(lines.length ? `Email: ${lines.join('. ')}.` : 'No important email.');
}
if (stale.length) spoken.push(`${plural(stale.length, 'reminder from before today is', 'reminders from before today are')} still open: ${list(stale.map((s) => s.title), 3)}. Say "close them", or "keep" and a name to leave one.`);

// ---- push text ----
const bits = [];
if (weather) bits.push(`${weather.temp_c}° ${weather.condition}`);
bits.push(`${schedule.length} on today`);
if (tasksDue.length) bits.push(plural(tasksDue.length, 'task due', 'tasks due'));
if (datesSoon.length && datesSoon[0].days <= 3) bits.push(`${datesSoon[0].title} ${datesSoon[0].when}`);
if (emailSynced && importantMail) bits.push(`${importantMail} important mail`);
if (college.total) bits.push(`${college.total} college ${college.total === 1 ? 'task' : 'tasks'} open`);
if (stale.length) bits.push(`${stale.length} old ${stale.length === 1 ? 'reminder' : 'reminders'} to close`);
const push = { title: greeting, body: `${DAY_NAMES[nd.getUTCDay()]} ${nd.getUTCDate()} ${MONTH_NAMES[nd.getUTCMonth()].slice(0, 3)}. ${bits.join(', ')}.`.slice(0, 300) };

return [{
  json: {
    ok: true, mode, today, bark_key: data.bark_key || '', generated_at: isoIst(now), greeting, date_text: dateText,
    weather, has_home: !!home, schedule, calendar_ok: calendarOk, tasks_due: tasksDue, dates_soon: datesSoon, habits, college, email: { synced: emailSynced, ...mail }, stale,
    spoken: spoken.join(' '), push,
  },
}];

// Node "Answer": what the app receives. The Bark key is never part of it.
const b = Object.assign({}, $input.first().json || {});
delete b.bark_key;
delete b.mode;
return [{ json: b }];
